Section Run.
Hypothesis PMODE : NESKA.spa_mode P.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (V2 cls r ov osk oec cat : Z).
Variables (en : enc) (k : NESK.sink) (b e : bool) (ea : NECS.eargs).
Local Notation sp := (V2 + cls).
Local Notation spc := (V2 - 128).
Local Notation SCR := (PMSPA.pm_scr 4).
(* [comment removed for export] *)
