Lemma keep_objs (LBf : list (Z * Z)) (FFx : list fframe) LKx crx Awx spx scrx Wx (Ma Mb : mem) {Mh : mem} Vx (en1 : enc) :
  ri_inv HI LBf FFx LKx crx Awx Mh Vx -> (forall f, In f FF -> In f FFx) -> L5SAR.ek L ar LBf FF spx scrx Wx Ma Mb -> PMKA.wapp Wx ->
  incl (enc_own en1) LBf -> incl (NESK.sink_own k) LBf ->
  (forall i, ov <= i < ov + 56 -> L5.outside Wx i) -> (forall i, osk <= i < osk + 24 -> L5.outside Wx i) ->
  (forall q c i, In (q, c) LBf -> q <= i < q + c -> L5.outside Wx i) ->
  enc_atA Ma ov osk en1 -> sink_atA Ma osk k ->
  enc_atA Mb ov osk en1 /\ sink_atA Mb osk k.
Proof.
